import sys, re, os, subprocess

def process_diff(lines):
    file_a, file_b = None, None
    hunks = []

    i = 0
    while i < len(lines):
        line = lines[i].rstrip('\n')
        if line.startswith('--- '):
            file_a = line[4:].split('\t')[0]
            if file_a.startswith('a/'): file_a = file_a[2:]
        elif line.startswith('+++ '):
            file_b = line[4:].split('\t')[0]
            if file_b.startswith('b/'): file_b = file_b[2:]

            print(f"\n\033[34m{file_a} ⟶   {file_b}\033[0m")
            print(f"\033[34m{'─' * 80}\033[0m")
            print()

        elif line.startswith('@@ '):
            # Parse hunk header
            m = re.match(r'@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@', line)
            if m:
                z = m.group(1)
                print(f"\033[34m───\033[0m\033[34m┐\033[0m")
                print(f"\033[34m{z}\033[0m: \033[34m│\033[0m")
                print(f"\033[34m───\033[0m\033[34m┘\033[0m")
        elif file_a and file_b:
            if line.startswith(' '):
                print(f"\033[38;5;231m{line[1:]}\033[0m")
            elif line.startswith('-'):
                print(f"\033[48;5;52m{line[1:]}\033[0m\033[48;5;52m\033[0K\033[0m")
            elif line.startswith('+'):
                print(f"\033[48;5;22;38;5;231m{line[1:]}\033[0m\033[48;5;22m\033[0K\033[0m")
        i += 1

if len(sys.argv) > 2:
    out = subprocess.check_output(['diff', '-u', sys.argv[1], sys.argv[2]], text=True)
    process_diff(out.splitlines(True))
else:
    process_diff(sys.stdin.readlines())
