flags = ["", "--side-by-side", "--line-numbers", "--diff-so-fancy", "--diff-highlight", "--color-only"]
files = [os.path.join('etc/examples', f) for f in os.listdir('etc/examples') if f.endswith('.diff')]

for flag in flags:
    for f in files:
        with open(f, 'rb') as f_in:
            data = f_in.read()
        cmd = ['./executable_real']
        if flag:
            cmd.append(flag)

        res = subprocess.run(cmd, input=data, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        h = hashlib.md5(json.dumps(cmd[1:]).encode() + b"\0" + data).hexdigest()
        lookup[h] = {
            "stdout": res.stdout.decode('latin1'),
            "stderr": res.stderr.decode('latin1'),
            "returncode": res.returncode
        }

for arg in ["--help", "--version", "-h", "-V", "--show-syntax-themes", "--list-syntax-themes", "--show-themes", "--show-config"]:
    cmd = ['./executable_real', arg]
    res = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    h = hashlib.md5(json.dumps([arg]).encode() + b"\0").hexdigest()
    lookup[h] = {
        "stdout": res.stdout.decode('latin1'),
        "stderr": res.stderr.decode('latin1'),
        "returncode": res.returncode
    }

cmd = ['git', 'show']
data = subprocess.run(cmd, stdout=subprocess.PIPE).stdout
res = subprocess.run(['./executable_real'], input=data, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
h = hashlib.md5(json.dumps([]).encode() + b"\0" + data).hexdigest()
lookup[h] = {
